/**
 * First Slack paint: ack the parent and raise the thinking chip.
 * Inbound fires this before send(); turn.started is the backstop.
 */
import { addReaction, removeReaction, setThreadStatus } from "./api.js";
import { SLACK_DEFAULT_LOADING_MESSAGES } from "./constants.js";
import { defaultSlackLog } from "./log.js";
export const START_CHIP = SLACK_DEFAULT_LOADING_MESSAGES[0];
export async function paintTurnStart(args) {
    if (args.channelId === "" || args.threadTs === "" || args.ack === "") {
        return;
    }
    const log = args.log ?? defaultSlackLog;
    const [react, status] = await Promise.all([
        addReaction({
            botToken: args.botToken,
            channel: args.channelId,
            ts: args.threadTs,
            name: args.ack,
        }),
        setThreadStatus({
            botToken: args.botToken,
            channelId: args.channelId,
            threadTs: args.threadTs,
            status: START_CHIP,
        }),
    ]);
    if (!react.ok && react.error !== "already_reacted") {
        log.warn("agentic ack failed", {
            error: react.error,
            channel: args.channelId,
            ts: args.threadTs,
        });
    }
    if (!status.ok) {
        log.warn("agentic status failed", {
            error: status.error,
            channel: args.channelId,
            thread_ts: args.threadTs,
        });
    }
}
export async function retractTurnStart(args) {
    if (args.channelId === "" || args.threadTs === "" || args.ack === "") {
        return;
    }
    const log = args.log ?? defaultSlackLog;
    const [react, status] = await Promise.all([
        removeReaction({
            botToken: args.botToken,
            channel: args.channelId,
            ts: args.threadTs,
            name: args.ack,
        }),
        setThreadStatus({
            botToken: args.botToken,
            channelId: args.channelId,
            threadTs: args.threadTs,
            status: "",
        }),
    ]);
    if (!react.ok && react.error !== "no_reaction") {
        log.warn("agentic ack retract failed", {
            error: react.error,
            channel: args.channelId,
            ts: args.threadTs,
        });
    }
    if (!status.ok) {
        log.warn("agentic status retract failed", {
            error: status.error,
            channel: args.channelId,
            thread_ts: args.threadTs,
        });
    }
}
